            "where", "with", "yield"
        };

        /*
         * Code Rule RJIT_CR_BC_C_00006 emphasizes the importance of avoiding partial classes in production code.
         */
        [TestMethod]
        public void Do_Not_Use_Reserved_Key_Words_As_Record_Name()
        {
            var result = (from @record in Records
                          from keyword in reservedKeywords
                          where @record.Name.ToLower() == keyword
                          select new
                          {
                              Error = $@"
Do not use reserved keywords as record name. This can cause in serious compiler errors or unexpected behavior.
----------------------------------------------------------------------------------------------------------------------------
FullName:         {@record.FullQualifiedName}
----------------------------------------------------------------------------------------------------------------------------
Reserved Keyword: {keyword}
----------------------------------------------------------------------------------------------------------------------------
Class:   

{@record.SyntaxTree.FormatSyntaxTree()}
----------------------------------------------------------------------------------------------------------------------------
"
                          }).ToImmutableList();

            Assert.IsTrue(result.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_BC_C_00006

Do not use resevered keywords or contextual keywords as class name. Found '{result.Count}':{Environment.NewLine}{result.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
